// Minimal fetch wrapper
async function fetchWithCache(url, opts = {}) {
  const cacheKey = url;
  const cache = await caches.open('liveinfo-cache');
  // Try cache first
  const cached = await cache.match(cacheKey);
  if (cached) {
    const text = await cached.text();
    try { return JSON.parse(text); } catch { /* fallthrough */ }
  }
  // Fallback to network
  const res = await fetch(url, opts);
  if (res.ok) {
    const clone = res.clone();
    cache.put(cacheKey, clone);
    return res.json();
  }
  throw new Error('Network error');
}
```
```javascript
// Minimal WebSocket wrapper
function createWebSocket(url, onMessage) {
  let ws;
  let delay = 1000;
  let stopped = false;
  const connect = () => {
    if (stopped) return;
    ws = new WebSocket(url);
    ws.addEventListener('message', (e) => onMessage(JSON.parse(e.data)));
    ws.addEventListener('close', () => {
      if (stopped) return;
      setTimeout(connect, delay);
      delay = Math.min(delay * 2, 30000);
    });
  };
  connect();
  return {
    close() { stopped = true; ws && ws.close(); },
    send(d) { ws && ws.readyState === WebSocket.OPEN && ws.send(JSON.stringify(d)); }
  };
}
```
